    return null;
  end if;
  header := nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-bs-actor';
  return case when header ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then header::uuid end;
exception when others then
