CREATE OR REPLACE FUNCTION better_supabase.cart_discounts(p_cart uuid, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cart record;
  v_promo record;
  v_reason text;
  v_eligible text[];
  v_base bigint;
  v_rem jsonb;
  v_disc jsonb := '{}';
  v_applied jsonb := '[]';
  v_problems jsonb := '[]';
  v_free boolean := false;
  v_stackable boolean := true;
  v_amount bigint;
  v_left bigint;
  v_share bigint;
  v_line_rem bigint;
  v_id text;
begin
  select x."tenant_id" as tenant, x."user_id" as owner, x."currency" as currency, x."email" as email
  into v_cart from "better_supabase"."carts" x where x."id" = p_cart;
  select coalesce(jsonb_object_agg(e ->> 'id', (e ->> 'subtotal')::bigint), '{}') into v_rem
  from jsonb_array_elements(p_lines) e;
  for v_promo in
    select x."id" as id, x."name" as name, x."kind" as kind, x."percent" as percent,
      x."currency" as currency, x."amount" as amount, x."min_subtotal" as min_subtotal,
      x."scope" as scope, x."target_ids" as targets, x."usage_limit" as usage_limit,
      x."per_customer_limit" as per_customer_limit, x."redemptions" as used, x."stackable" as stackable,
      x."automatic" as automatic,
      (x."active" and (x."starts_at" is null or x."starts_at" <= now())
        and (x."ends_at" is null or x."ends_at" > now())) as live,
      code.id as code_id, code.code as code, code.usage_limit as code_limit, code.used as code_used
    from "better_supabase"."promotions" x
    left join lateral (
      select k."id" as id, k."code" as code, k."usage_limit" as usage_limit, k."redemptions" as used
      from "better_supabase"."cart_promotion_codes" y join "better_supabase"."promotion_codes" k on k."id" = y."code_id"
      where y."cart_id" = p_cart and k."promotion_id" = x."id"
      order by y."created_at", k."id"
      limit 1
    ) code on true
    where x."tenant_id" = v_cart.tenant and (code.id is not null or (x."automatic" and x."active"))
    order by x."priority" desc, x."created_at", x."id"
  loop
    v_reason := null;
    if not v_promo.live then
      v_reason := 'expired';
    elsif (v_promo.usage_limit is not null and v_promo.used >= v_promo.usage_limit)
      or (v_promo.code_limit is not null and v_promo.code_used >= v_promo.code_limit)
      or (v_promo.per_customer_limit is not null
        and (select count(*) from "better_supabase"."promotion_redemptions" y where y."promotion_id" = v_promo.id and y."status" = 'redeemed'
      and (y."customer_id" = v_cart.owner or (v_cart.email is not null and lower(y."email") = lower(v_cart.email)))) >= v_promo.per_customer_limit) then
      v_reason := 'limit_reached';
    elsif v_promo.currency is not null and v_promo.currency <> v_cart.currency then
      v_reason := 'currency';
    else
      select coalesce(array_agg(e ->> 'id' order by n), '{}'), coalesce(sum((e ->> 'subtotal')::bigint), 0)
      into v_eligible, v_base
      from jsonb_array_elements(p_lines) with ordinality as l(e, n)
      where v_promo.scope = 'order'
      or (v_promo.scope = 'products' and (e ->> 'productId')::uuid = any (v_promo.targets))
      or (v_promo.scope = 'categories' and exists (
      with recursive d (id) as (
        select unnest(v_promo.targets)
        union
        select x."id" from "better_supabase"."categories" x join d on x."parent_id" = d.id
      )
      select 1 from "better_supabase"."product_categories" y where y."product_id" = (e ->> 'productId')::uuid and y."category_id" in (select id from d)
    ))
      or (v_promo.scope = 'collections' and exists (select 1 from "better_supabase"."collection_products" y where y."product_id" = (e ->> 'productId')::uuid and y."collection_id" = any (v_promo.targets)));
      if cardinality(v_eligible) = 0 then
        v_reason := 'not_applicable';
      elsif v_promo.min_subtotal is not null and v_base < v_promo.min_subtotal then
        v_reason := 'min_subtotal';
      elsif jsonb_array_length(v_applied) > 0 and not (v_stackable and v_promo.stackable) then
        v_reason := 'not_combinable';
      end if;
    end if;
    if v_reason is not null then
      if v_promo.code_id is not null then
        v_problems := v_problems || jsonb_build_array(jsonb_build_object('problem', 'promotion_unavailable',
          'promotionId', v_promo.id, 'code', v_promo.code, 'reason', v_reason));
      end if;
      continue;
    end if;
    v_amount := 0;
    if v_promo.kind = 'percentage' then
      foreach v_id in array v_eligible loop
        v_line_rem := (v_rem ->> v_id)::bigint;
        v_share := least("better_supabase"."round_half_even"(v_line_rem * v_promo.percent / 100), v_line_rem);
        v_rem := jsonb_set(v_rem, array[v_id], to_jsonb(v_line_rem - v_share));
        v_disc := jsonb_set(v_disc, array[v_id], to_jsonb(coalesce((v_disc ->> v_id)::bigint, 0) + v_share));
        v_amount := v_amount + v_share;
      end loop;
    elsif v_promo.kind = 'fixed' then
      select coalesce(sum((v_rem ->> e)::bigint), 0) into v_base from unnest(v_eligible) e;
      v_left := least(v_promo.amount, v_base);
      if v_base > 0 then
        foreach v_id in array v_eligible loop
          v_line_rem := (v_rem ->> v_id)::bigint;
          v_share := floor(least(v_promo.amount, v_base)::numeric * v_line_rem / v_base)::bigint;
          v_rem := jsonb_set(v_rem, array[v_id], to_jsonb(v_line_rem - v_share));
          v_disc := jsonb_set(v_disc, array[v_id], to_jsonb(coalesce((v_disc ->> v_id)::bigint, 0) + v_share));
          v_left := v_left - v_share;
        end loop;
        foreach v_id in array v_eligible loop
          exit when v_left = 0;
          if (v_rem ->> v_id)::bigint > 0 then
            v_rem := jsonb_set(v_rem, array[v_id], to_jsonb((v_rem ->> v_id)::bigint - 1));
            v_disc := jsonb_set(v_disc, array[v_id], to_jsonb(coalesce((v_disc ->> v_id)::bigint, 0) + 1));
            v_left := v_left - 1;
          end if;
        end loop;
        v_amount := least(v_promo.amount, v_base);
      end if;
    else
      v_free := true;
    end if;
    v_stackable := v_stackable and v_promo.stackable;
    v_applied := v_applied || jsonb_build_array(jsonb_build_object('promotionId', v_promo.id, 'name', v_promo.name,
      'kind', v_promo.kind, 'codeId', v_promo.code_id, 'code', v_promo.code, 'amount', v_amount::text));
  end loop;
  select coalesce(jsonb_object_agg(key, value #>> '{}'), '{}') into v_disc from jsonb_each(v_disc);
  return jsonb_build_object('lines', v_disc, 'applied', v_applied, 'freeShipping', v_free, 'problems', v_problems);
end;
$function$

functions.definition:
declare
  v_cart record;
  v_line record;
  v_rate record;
  v_amount bigint;
  v_lines jsonb := '[]';
  v_problems jsonb := '[]';
  v_subtotal bigint := 0;
  v_discount bigint := 0;
  v_shipping bigint := 0;
  v_weight bigint := 0;
  v_ships boolean := false;
  v_free boolean := false;
  v_promo jsonb;
  v_discounts jsonb := '{}';
  v_applied jsonb := '[]';
  v_snapshot jsonb;
  v_country text;
begin
  select x."tenant_id" as tenant, x."currency" as currency, x."price_list_id" as price_list,
    x."shipping_address" as shipping_address, x."shipping_rate_id" as shipping_rate,
    x."user_id" as owner, x."status" as status, x."email" as email, x."billing_address" as billing_address
  into v_cart from "better_supabase"."carts" x where x."id" = p_cart;
  for v_line in
    select l."id" as id, l."variant_id" as variant, l."quantity" as quantity, l."unit_amount" as unit_amount,
      cv."sku" as sku, concat_ws(' / ', cp."title", nullif(cv."title", '')) as title, cp."id" as product, cp."status" as status,
      cp."kind" as kind, cv."weight_grams" as weight
    from "better_supabase"."cart_lines" l
    join "better_supabase"."product_variants" cv on cv."id" = l."variant_id"
    join "better_supabase"."products" cp on cp."id" = cv."product_id"
    where l."cart_id" = p_cart
    order by l."created_at", l."id"
  loop
    v_amount := ("better_supabase"."variant_price"(v_line.variant, v_cart.currency, v_cart.price_list, null) ->> 'amount')::bigint;
    if v_line.status <> 'active' or v_amount is null then
      v_problems := v_problems || jsonb_build_array(jsonb_build_object('lineId', v_line.id, 'variantId', v_line.variant,
        'problem', case when v_line.status <> 'active' then 'unavailable' else 'unpriced' end));
      continue;
    end if;
    if v_line.unit_amount is distinct from v_amount then
      update "better_supabase"."cart_lines" x set "unit_amount" = v_amount, "updated_at" = now() where x."id" = v_line.id;
    end if;
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'id', v_line.id, 'variantId', v_line.variant, 'productId', v_line.product, 'sku', v_line.sku, 'title', v_line.title,
      'quantity', v_line.quantity, 'unitAmount', v_amount::text, 'previousUnitAmount', v_line.unit_amount::text,
      'subtotal', (v_amount * v_line.quantity)::text, 'requiresShipping', v_line.kind = 'physical'));
    v_subtotal := v_subtotal + v_amount * v_line.quantity;
    if v_line.kind = 'physical' then
      v_ships := true;
      v_weight := v_weight + coalesce(v_line.weight, 0)::bigint * v_line.quantity;
    end if;
  end loop;
  if jsonb_array_length(v_lines) > 0 then
    v_promo := "better_supabase"."cart_discounts"(p_cart, v_lines);
    v_discounts := coalesce(v_promo -> 'lines', '{}'::jsonb);
    v_applied := coalesce(v_promo -> 'applied', '[]'::jsonb);
    v_free := coalesce((v_promo ->> 'freeShipping')::boolean, false);
    v_problems := v_problems || coalesce(v_promo -> 'problems', '[]'::jsonb);
  end if;
  select coalesce(jsonb_agg(e.l || jsonb_build_object(
      'discount', coalesce(v_discounts ->> (e.l ->> 'id'), '0'),
      'total', ((e.l ->> 'subtotal')::bigint - coalesce((v_discounts ->> (e.l ->> 'id'))::bigint, 0))::text) order by e.n), '[]'::jsonb),
    coalesce(sum(coalesce((v_discounts ->> (e.l ->> 'id'))::bigint, 0)), 0)
  into v_lines, v_discount
  from jsonb_array_elements(v_lines) with ordinality as e(l, n);
  v_country := v_cart.shipping_address ->> 'country';
  if v_ships and v_cart.shipping_rate is not null then
    select x."id" as id, x."name" as name, x."countries" as countries, x."kind" as kind,
      x."amount" as amount, x."amount_per_kg" as per_kg, x."free_over" as free_over
    into v_rate from "better_supabase"."shipping_rates" x
    where x."id" = v_cart.shipping_rate and x."active" and x."currency" = v_cart.currency;
    if not found or (cardinality(v_rate.countries) > 0 and (v_country is null or not v_country = any (v_rate.countries))) then
      v_problems := v_problems || jsonb_build_array(jsonb_build_object('problem', 'shipping_unavailable'));
    else
      v_shipping := v_rate.amount + case when v_rate.kind = 'weight' then (v_rate.per_kg * v_weight + 999) / 1000 else 0 end;
      if v_free or (v_rate.free_over is not null and v_subtotal - v_discount >= v_rate.free_over) then
        v_shipping := 0;
      end if;
      v_snapshot := jsonb_build_object('rateId', v_rate.id, 'name', v_rate.name, 'amount', v_shipping::text);
    end if;
  elsif v_ships and exists (
    select 1 from "better_supabase"."shipping_rates" x
    where x."tenant_id" = v_cart.tenant and x."active" and x."currency" = v_cart.currency
  ) then
    v_problems := v_problems || jsonb_build_array(jsonb_build_object('problem', 'shipping_required'));
  end if;
  return jsonb_build_object(
    'cartId', p_cart, 'organizationId', v_cart.tenant, 'customerId', v_cart.owner, 'status', v_cart.status,
    'email', v_cart.email, 'shippingAddress', v_cart.shipping_address, 'billingAddress', v_cart.billing_address,
    'currency', v_cart.currency, 'lines', v_lines,
    'subtotal', v_subtotal::text, 'discountTotal', v_discount::text, 'shippingTotal', v_shipping::text,
    'total', (v_subtotal - v_discount + v_shipping)::text, 'requiresShipping', v_ships,
    'weightGrams', v_weight::text, 'shipping', v_snapshot, 'promotions', v_applied, 'problems', v_problems);
end;

