      select count(*) from "better_supabase"."waitlist_entries" w where w."status" = 'waiting' and w."position" <= v_row."position"
    ) else (
      select count(*) + 1 from "better_supabase"."waitlist_entries" w where w."status" = 'waiting'
    ) end,
    'status', 'waiting'
  );
end;
$function$

