    if v_hook is not null then
      execute format('select %s($1::uuid, $2::boolean)', v_hook::oid::regproc)
        using v_id, v_created;
    end if;
  end;
  return jsonb_build_object('id', v_id, 'slug', v_slug, 'status', v_status);
