select count(*)::integer from "better_supabase"."workflow_start_requests" x
where x."key" = workflow_admission_active.key
  and (
    (x."status" = 'pending' and x."claimed_until" >= now())
    or (x."status" = 'started' and not exists (
      select 1 from "better_supabase"."workflow_runs" y
      where y."external_id" = x."run_id" and y."status" in ('completed', 'failed', 'cancelled')
    ) and x."started_at" > now() - interval '1 day')
  );

select coalesce(array_agg(distinct x.p order by x.p), '{}'::text[])
from (
  select coalesce(
    '{}'::jsonb ->> (n.value ->> 'step'),
    (select coalesce('{}'::jsonb ->> s."operation", s."operation")
      from "better_supabase"."workflow_step_library" s where s."name" = n.value ->> 'step'),
    'workflow.run'
  ) as p
  from jsonb_array_elements(
    case when jsonb_typeof(workflow_graph_permissions.graph -> 'nodes') = 'array'
      then workflow_graph_permissions.graph -> 'nodes' else '[]'::jsonb end
  ) n
  where n.value ->> 'kind' = 'step'
) x;

